document.querySelectorAll('[data-package]').forEach(link=>link.addEventListener('click',()=>{document.querySelector('#package').value=link.dataset.package}));
document.querySelector('#inquiry-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const body=`Name: ${data.get('name')}\nBusiness: ${data.get('business')}\nWebsite: ${data.get('website')||'None yet'}\nScope: ${data.get('package')}\n\nWhat I need:\n${data.get('needs')}`;window.location.href=`mailto:anthonyalfano157@gmail.com?subject=${encodeURIComponent('Website inquiry — '+data.get('business'))}&body=${encodeURIComponent(body)}`;document.querySelector('#form-status').textContent='Your inquiry is ready in your email app. If it did not open, email your details directly to anthonyalfano157@gmail.com. Nothing has been submitted yet.'});
